-- =====================================================================
-- Estoque Calendário — schema do Supabase
-- Cole este arquivo inteiro no SQL Editor do Supabase (Supabase → seu
-- projeto → SQL Editor → New query) e clique em "Run".
-- =====================================================================

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------------
-- TABELA: produtos (banco de produtos — catálogo Garmin + itens manuais)
-- ---------------------------------------------------------------------
create table if not exists produtos (
  id uuid primary key default gen_random_uuid(),
  barcode text,
  sku text not null,
  descricao text not null,
  valor numeric,
  foto text,
  origem text default 'manual',
  created_at timestamptz not null default now()
);

create index if not exists produtos_barcode_idx on produtos (barcode);
create index if not exists produtos_sku_idx on produtos (sku);

-- ---------------------------------------------------------------------
-- TABELA: vendas (itens vendidos, um item por linha, agrupados por dia)
-- ---------------------------------------------------------------------
create table if not exists vendas (
  id uuid primary key default gen_random_uuid(),
  data date not null,
  descricao text not null,
  sku text not null,
  vendedor text not null,
  nfe text not null,
  quantidade text not null,
  valor text not null,
  created_at timestamptz not null default now()
);

create index if not exists vendas_data_idx on vendas (data);

-- ---------------------------------------------------------------------
-- SEGURANÇA (RLS): só usuários autenticados (logados) podem ler/gravar.
-- Não há isolamento por usuário — é um único sistema de loja compartilhado
-- entre todos os funcionários autorizados, como o resto do site já assume.
-- ---------------------------------------------------------------------
alter table produtos enable row level security;
alter table vendas enable row level security;

create policy "Usuarios logados podem ler produtos"
  on produtos for select to authenticated using (true);
create policy "Usuarios logados podem inserir produtos"
  on produtos for insert to authenticated with check (true);
create policy "Usuarios logados podem excluir produtos"
  on produtos for delete to authenticated using (true);

create policy "Usuarios logados podem ler vendas"
  on vendas for select to authenticated using (true);
create policy "Usuarios logados podem inserir vendas"
  on vendas for insert to authenticated with check (true);
create policy "Usuarios logados podem atualizar vendas"
  on vendas for update to authenticated using (true) with check (true);
create policy "Usuarios logados podem excluir vendas"
  on vendas for delete to authenticated using (true);

-- ---------------------------------------------------------------------
-- CATÁLOGO INICIAL DA GARMIN (466 produtos, fotos já casadas pelo SKU
-- exato de cada um — 39 itens sem foto porque não existem mais na loja
-- pública, como já expliquei antes).
-- ---------------------------------------------------------------------





-- ---------------------------------------------------------------------
-- MIGRAÇÃO: adiciona a coluna "valor" (preço) à tabela produtos.
-- Rode SÓ este bloco no SQL Editor do Supabase se o banco já existir —
-- não rode o arquivo inteiro de novo, isso duplicaria o catálogo acima.
-- ---------------------------------------------------------------------
alter table produtos add column if not exists valor numeric;

-- ---------------------------------------------------------------------
-- MIGRAÇÃO: permite editar itens de venda já lançados (antes só dava pra
-- inserir/excluir). Rode SÓ este bloco no SQL Editor do Supabase.
-- (drop + create pra poder rodar de novo sem erro caso já exista)
-- ---------------------------------------------------------------------
drop policy if exists "Usuarios logados podem atualizar vendas" on vendas;
create policy "Usuarios logados podem atualizar vendas"
  on vendas for update to authenticated using (true) with check (true);